INSERT INTO `biz_plant_dict` VALUES (1, '比特幼苗', '从数据废墟中萌发的初级生命体，叶脉中流淌着二进制能量', 800, 'plant_bit_seedling', '/api/static/plants/plant_bit_seedling.png', '#32CD32', 1, 1, 100, 1, 1775569314000, 1775758541320, 0);
INSERT INTO `biz_plant_dict` VALUES (2, '数据蘑菇', '成簇生长在数据腐殖层上的真菌，发光强度随网络流量波动', 200, 'plant_data_shrooms', '/api/static/plants/plant_data_shrooms.png', '#9370DB', 1, 1, 50, 1, 1775569314000, 1775833254407, 0);
INSERT INTO `biz_plant_dict` VALUES (3, '电路垂柳', '枝条如电路板般精密排列，风中摇曳时发出微弱的电流声', 50, 'plant_circuit_willow', '/api/static/plants/plant_circuit_willow.png', '#00CED1', 3, 3, 300, 1, 1775569314000, 1775747146674, 0);
INSERT INTO `biz_plant_dict` VALUES (4, '霓虹棕榈', '热带数据风暴中进化出的耐旱植物，叶片闪烁着温暖的橙光', 50, 'plant_neon_palm', '/api/static/plants/plant_neon_palm.png', '#f114de', 3, 3, 300, 1, 1775569314000, 1775754089832, 0);
INSERT INTO `biz_plant_dict` VALUES (5, '水晶灌木', '罕见的晶体植物，内部封存着古老的代码片段，发出梦幻粉光', 100, 'plant_neon_crystal', '/api/static/plants/plant_neon_crystal.png', '#06e311', 2, 2, 150, 1, 1775569314000, 1775833605756, 0);
INSERT INTO `biz_plant_dict` VALUES (6, '量子仙人掌', '变异仙人掌，据说能感知量子涨落，浑身散发着金色光芒', 100, 'plant_quantum_cactus', '/api/static/plants/plant_quantum_cactus.png', '#becf0a', 2, 2, 100, 1, 1775569314000, 1775754077071, 0);
INSERT INTO `biz_plant_dict` VALUES (7, '数据丝柏', '一棵高大的数据植被，分节的树干模仿复杂的代码流，顶部是密集的霓虹青叶群。', 50, 'plant_data_cypress', '/api/static/plants/plant_data_cypress.png', '#1df2dd', 3, 3, 500, 1, 1775751319238, 1775833223769, 0);
INSERT INTO `biz_plant_dict` VALUES (8, '星尘蕨', '复杂的羽状复叶嵌入宇宙尘埃和光迹。', 200, 'plant_stardust_fern', '/api/static/plants/plant_stardust_fern.png', '#00ff88', 1, 1, 100, 1, 1775751649480, 1775751649480, 0);
INSERT INTO `biz_plant_dict` VALUES (9, '云端古木', '一棵古老的树，拥有广阔的云状树冠，扎根于超高密度数据云端。', 10, 'plant_cloud_ancient_tree', '/api/static/plants/plant_cloud_ancient_tree.png', '#fed805', 4, 4, 500, 1, 1775752442657, 1777012583785, 0);
INSERT INTO `biz_plant_dict` VALUES (10, '核心葵', '一个充满活力的花卉数据结构，辐射强烈脉冲的蓝色能量。', 100, 'plant_core_sunflower', '/api/static/plants/6de26830-4e97-46fd-acd8-081cfa7c4c8e.png', '#2070bb', 2, 1, 50, 1, 1775754221220, 1775833200219, 0);
INSERT INTO `biz_plant_dict` VALUES (11, '共振风铃草', '成簇的精致数据风铃花，在多个风铃接近时同步脉冲，生成复杂的共鸣能量波。', 50, 'plant_resonance_bellflower', '/api/static/plants/992b3602-74c8-4e8f-8fd9-0af1f48495a9.png', '#1165be', 3, 1, 100, 1, 1775754304013, 1775754320699, 0);
INSERT INTO `biz_plant_dict` VALUES (12, '晶格刺槐', '一个带有交织几何晶格树冠的保护性刺槐结构，武装有发光的像素荆棘以防御数据入侵。', 50, 'plant_lattice_acacia', '/api/static/plants/5f2659b5-4185-4123-9173-a658f40d0b30.png', '#d70c57', 3, 2, 150, 1, 1775754417422, 1775833636761, 0);
INSERT INTO `biz_plant_dict` VALUES (13, '以太珊瑚', '一个扎根于纯净以太池中的植物和珊瑚的多分支共生体，注入柔和的白色以太光，不断再生其晶体结构。', 25, 'plant_aether_coral', '/api/static/plants/123611da-6f15-4304-930c-0bd630de989c.png', '#fbfcf0', 3, 1, 100, 1, 1775754508235, 1775754508235, 0);
INSERT INTO `biz_plant_dict` VALUES (14, '流光蕊', '在极度纯净的“专注奇点”状态下罕见地凝结而成，完美的光谱和极致治愈能量的化体。', 5, 'plant_flowing_light_stamen', '/api/static/plants/plant_flowing_light_stamen.png', '#fbff00', 4, 1, 50, 1, 1775754722310, 1775754831451, 0);
